import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, vec4, texture, uniform, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // Parse text content with fallback to spec defaults
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textMap = {};
  for (const item of textItems) {
    if (item.role) {
      textMap[item.role] = item.text;
    }
  }

  const kicker = textMap.kicker ?? 'NOVA ATELIER / JOURNAL';
  const heroLine1 = textMap.heroLine1 ?? 'PRECISION IS';
  const heroLine2 = textMap.heroLine2 ?? 'A HABIT.';
  const body = textMap.body ?? 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.';
  const caption = textMap.caption ?? 'ISSUE 12 / JULY 2026';

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38'
  };

  // Create backdrop plane (7 x 5.5 units) with vertical TSL gradient + grain
  const backdropGeo = new THREE.PlaneGeometry(7, 5.5);

  // TSL shader: vertical gradient #0b0b10 (top) to #14141a (bottom) + grain
  const colorTop = color(colors.background);
  const colorBottom = color(colors.surface);
  const gradientNode = mix(colorTop, colorBottom, uv().y);

  // Simple grain: use time-seeded noise approximation
  const seed = uniform(Math.random());
  const noiseUv = uv().mul(50).add(seed);
  const grain = mix(0.98, 1.02, noiseUv.fract().mul(0.015));

  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: gradientNode.mul(grain),
    side: THREE.FrontSide
  });

  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = 0;
  group.add(backdrop);

  // Container for animated text blocks
  const textContainer = new THREE.Group();
  group.add(textContainer);

  // Helper to scale text from pixel space to scene units
  const scaleTextToScene = (textObj, sceneFontSize) => {
    // Approximate: fontAtlas renders at ~96 DPI; scale to 0.01 per scene unit
    const pixelFontSize = sceneFontSize * 100; // rough conversion
    textObj.scale.multiplyScalar(sceneFontSize / 2); // empirical scale factor
    return textObj;
  };

  // Kicker text (JetBrains Mono 700, uppercase, 18px, tracking 0.12em)
  const kickerObj = ctx.fontAtlas.createText(kicker.toUpperCase(), {
    fontSize: 18,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 2.16  // 0.12em at 18px
  });
  scaleTextToScene(kickerObj, 0.18); // ~0.18 scene units for 18px
  kickerObj.position.set(-3.1, 1.7, 0.01);
  kickerObj.userData.blockType = 'kicker';
  kickerObj.userData.baseY = 1.7;
  textContainer.add(kickerObj);

  // Hero line 1 (Lora 600, 124px, tracking -0.015em)
  const hero1Obj = ctx.fontAtlas.createText(heroLine1, {
    fontSize: 124,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: -1.86  // -0.015em at 124px
  });
  scaleTextToScene(hero1Obj, 0.62); // ~0.62 scene units for 124px
  hero1Obj.position.set(-3.1, 0.9, 0.01);
  hero1Obj.userData.blockType = 'hero';
  hero1Obj.userData.baseY = 0.9;
  textContainer.add(hero1Obj);

  // Hero line 2 (Lora 600, 124px, tracking -0.015em)
  const hero2Obj = ctx.fontAtlas.createText(heroLine2, {
    fontSize: 124,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: -1.86
  });
  scaleTextToScene(hero2Obj, 0.62);
  hero2Obj.position.set(-3.1, 0.25, 0.01);
  hero2Obj.userData.blockType = 'hero';
  hero2Obj.userData.baseY = 0.25;
  textContainer.add(hero2Obj);

  // Letterpress shadow effect for hero (duplicate planes behind)
  const hero1Shadow = ctx.fontAtlas.createText(heroLine1, {
    fontSize: 124,
    color: colors.ink,
    align: 'left',
    letterSpacingPx: -1.86
  });
  scaleTextToScene(hero1Shadow, 0.62);
  hero1Shadow.position.set(-3.1 + 0.02, 0.9 - 0.02, -0.01);
  hero1Shadow.userData.blockType = 'shadow';
  textContainer.add(hero1Shadow);

  const hero2Shadow = ctx.fontAtlas.createText(heroLine2, {
    fontSize: 124,
    color: colors.ink,
    align: 'left',
    letterSpacingPx: -1.86
  });
  scaleTextToScene(hero2Shadow, 0.62);
  hero2Shadow.position.set(-3.1 + 0.02, 0.25 - 0.02, -0.01);
  hero2Shadow.userData.blockType = 'shadow';
  textContainer.add(hero2Shadow);

  // Accent underline rule (2.2 x 0.05 units, #ff2a38, emissive 1.2)
  const ruleGeo = new THREE.PlaneGeometry(2.2, 0.05);
  const ruleMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.2
  });
  const rule = new THREE.Mesh(ruleGeo, ruleMat);
  rule.position.set(-3.1 + 1.1, -0.15, 0.02);
  rule.scale.x = 0;  // Start at scaleX 0 for draw animation
  rule.userData.blockType = 'rule';
  textContainer.add(rule);

  // Body paragraph (JetBrains Mono 400, 26px)
  const bodyObj = ctx.fontAtlas.createText(body, {
    fontSize: 26,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 450  // roughly 4.5 units wide
  });
  scaleTextToScene(bodyObj, 0.26); // ~0.26 scene units for 26px
  bodyObj.position.set(-3.1, -0.8, 0.01);
  bodyObj.userData.blockType = 'body';
  bodyObj.userData.baseY = -0.8;
  textContainer.add(bodyObj);

  // Caption (JetBrains Mono 400, 18px, tracking 0.08em)
  const captionObj = ctx.fontAtlas.createText(caption, {
    fontSize: 18,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 1.44  // 0.08em at 18px
  });
  scaleTextToScene(captionObj, 0.18);
  captionObj.position.set(-3.1, -1.9, 0.01);
  captionObj.userData.blockType = 'caption';
  captionObj.userData.baseY = -1.9;
  textContainer.add(captionObj);

  // Animation timeline: rise-in stagger + rule draw
  const timeline = gsap.timeline();
  const blocks = [kickerObj, hero1Obj, hero2Obj, bodyObj, captionObj];
  const shadows = [hero1Shadow, hero2Shadow];

  // Set initial opacity to 0 for all text
  blocks.forEach(block => {
    block.traverse(child => {
      if (child.material) {
        child.material.transparent = true;
        child.material.opacity = 0;
      }
    });
  });

  shadows.forEach(shadow => {
    shadow.traverse(child => {
      if (child.material) {
        child.material.transparent = true;
        child.material.opacity = 0;
      }
    });
  });

  // Animate blocks: rise-in with stagger
  blocks.forEach((block, i) => {
    const baseY = block.userData.baseY;
    block.position.y = baseY + 0.4;

    timeline.to(
      block.position,
      {
        y: baseY,
        duration: 0.7,
        ease: 'power3.out'
      },
      i * 0.08
    );

    // Fade in opacity
    block.traverse(child => {
      if (child.material) {
        timeline.to(
          child.material,
          {
            opacity: 1,
            duration: 0.7,
            ease: 'power2.out'
          },
          i * 0.08
        );
      }
    });
  });

  // Animate shadows in sync with hero blocks
  shadows.forEach((shadow, i) => {
    const shadowBaseY = shadow.position.y;
    shadow.position.y += 0.4;

    timeline.to(
      shadow.position,
      {
        y: shadowBaseY,
        duration: 0.7,
        ease: 'power3.out'
      },
      (i + 1) * 0.08  // hero blocks are at indices 1 and 2
    );

    shadow.traverse(child => {
      if (child.material) {
        timeline.to(
          child.material,
          {
            opacity: 1,
            duration: 0.7,
            ease: 'power2.out'
          },
          (i + 1) * 0.08
        );
      }
    });
  });

  // Rule draws after hero lands (at 0.7s + 80ms*2 + slight delay)
  timeline.to(
    rule.scale,
    {
      x: 1,
      duration: 0.5,
      ease: 'power1.inOut'
    },
    0.76  // 0.7 + 0.08 + 0.08 - after second hero line animation
  );

  // Cleanup function
  group.userData.cleanup = () => {
    timeline.kill();
    backdrop.geometry.dispose();
    backdrop.material.dispose();
    rule.geometry.dispose();
    rule.material.dispose();

    const disposeTree = (obj) => {
      obj.traverse(child => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    };

    disposeTree(kickerObj);
    disposeTree(hero1Obj);
    disposeTree(hero2Obj);
    disposeTree(hero1Shadow);
    disposeTree(hero2Shadow);
    disposeTree(bodyObj);
    disposeTree(captionObj);
  };

  return group;
}
